      "nl_subway": "Subway train",
      "nl_subway_notes": "Pain threshold for prolonged exposure.",
      "nl_threshold": "Threshold of hearing",
      "nl_threshold_notes": "Quietest sound a young healthy ear can detect.",
      "nl_traffic": "Heavy traffic",
      "nl_traffic_notes": "Long exposure can cause hearing damage.",
